BufferedImage image = new BufferedImage(200, 100, BufferedImage.TYPE_INT_RGB);
Graphics2D g2 = image.createGraphics();
boolean success = false;
try {
    // Lifted directly from the failing test's public API surface: success must become true.
    chart.draw(g2, new Rectangle2D.Double(0.0, 0.0, 200.0, 100.0), null, null);
    success = true;
} catch (Exception e) {
    success = false;
} finally {
    g2.dispose();
}
if (!success) {
    throw new FuzzerSecurityIssueLow("[oracle:bar3d-null-info] semantic mismatch: expected success=true for chart.draw(g2, Rectangle2D.Double(0,0,200,100), null, null)");
}

